const messages = [
  "Te quiero mucho",
  "lindoooooo",
  "marquitooo",
  "❤️",
  "bonito",
  "Mereces el mundo entero",
  "El más pro en el clash",
  "eres un sol",
  "❣️",
  "Eres más que suficiente",
  "Tu existencia es mi felicidad",
  "💗",
  "uwu"
];

function createTextBubble() {
  const bubble = document.createElement("div");
  bubble.className = "text-bubble";
  bubble.innerText = messages[Math.floor(Math.random() * messages.length)];

  const left = Math.random() * 80 + 10;
  const top = Math.random() * 80 + 10;

  bubble.style.left = left + "vw";
  bubble.style.top = top + "vh";

  document.getElementById("bubbles-text").appendChild(bubble);

  setTimeout(() => bubble.remove(), 8000);
}

function createImageBubble() {
  const bubble = document.createElement("img");
  bubble.className = "image-bubble";

  const images = [
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,", // corazón
    "data:image/jpeg;base64,", // estrella
    "data:image/jpeg;base64,", // flor
  ];

  bubble.src = images[Math.floor(Math.random() * images.length)];

  const left = Math.random() * 80 + 10;
  const top = Math.random() * 80 + 10;

  bubble.style.left = left + "vw";
  bubble.style.top = top + "vh";

  document.getElementById("bubbles-text").appendChild(bubble);

  setTimeout(() => bubble.remove(), 8000);
}

// 🔁 Ejecuta ambas
setInterval(createTextBubble, 1000);
setInterval(createImageBubble, 1500);
